                new WeekendPackagePlan(), new LongStayPlan())
                .forEach(plan -> BY_CODE.put(plan.code(), plan));
    }

    private RatePlans() {}

    public static Optional<RatePlan> find(String code) {
        return Optional.ofNullable(BY_CODE.get(code));
    }
}
