    void corporateWeekendAndLongStayExamples() throws Exception {
        JsonNode corp = json(book(201, "2027-03-10", "2027-03-12", 2, "CORPORATE", "TECNOSUL"));
        assertEquals("779.80", corp.get("subtotal").decimalValue().toPlainString());
        assertEquals("93.58", corp.get("discount").decimalValue().toPlainString());
        assertEquals("686.22", corp.get("total").decimalValue().toPlainString());

